1687	/**
1688	 * Reclaim build/ingest space. `docker builder prune -af` reclaimed 7.1 GB in the
1689	 * field immediately after two image builds, which is the difference between a
1690	 * working bring-up and ENOSPC. Dangling images go too. Deliberately NOT
1691	 * `image prune -a` / `container prune` — those would delete images we have just
1692	 * transferred but not yet started.
1693	 */
1694	async function pruneDocker(conn: Client): Promise<number> {
1695	  const before = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
1696	  await sh(conn, `docker builder prune -af >/dev/null 2>&1; docker image prune -f >/dev/null 2>&1; true`, INSTALL_TIMEOUT_MS);
1697	  const after = (await availBytes(conn, DOCKER_STORES[0])) ?? 0;
1698	  return Math.max(0, after - before);
1699	}
