1701	// ===========================================================================
1702	// DOCKER IMAGES — pull public, save/load everything else
1703	// ===========================================================================
1704	/**
1705	 * Make one image exist on the TARGET.
1706	 *
1707	 *   already present → nothing (a re-run must not re-transfer gigabytes)
1708	 *   public registry → `docker pull` (fast, and costs no source bandwidth)
1709	 *   otherwise       → `docker save | gzip` on the source, streamed straight
1710	 *                     through the SSH channel into `gunzip | docker load`
1711	 *
1712	 * The locally-built case is the one that silently broke a real migration: the
1713	 * engine copied files and named volumes but never the IMAGE, so standalone
1714	 * containers could never start. A pull that fails also falls back to save/load,
1715	 * so a private registry the new box cannot authenticate to still works.
1716	 *
1717	 * `ref` is validated by validImageRef before it reaches any command; success is
1718	 * confirmed with `docker image inspect` rather than trusting an exit code
1719	 * through a pipeline.
1720	 */
1721	async function ensureImage(
1722	  conn: Client,
1723	  ref: string,
1724	  local: boolean,
1725	  onSource: (cmd: string) => string,
1726	  priv: string,
1727	  say: (line: string) => Promise<void>
1728	): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
1729	  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };
1730	
1731	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1732	    return { status: "present", detail: "already on the new server" };
1733	  }
1734	
1735	  if (!local) {
1736	    // A multi-gigabyte pull is one of the three steps that can sit silent for
1737	    // minutes, so it narrates itself (see withHeartbeat).
1738	    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
1739	      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
1740	    );
1741	    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1742	      return { status: "pulled", detail: "pulled from its registry" };
1743	    }
1744	    const why = tailOf(pull, 1, 120);
1745	    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
1746	  }
1747	
1748	  // `docker save | gzip -1` on the source → `gunzip | docker load` on the target,
1749	  // through the SSH channel we already hold. gzip -1 because these links are
1750	  // usually faster than the CPU and the layers are mostly already compressed.
1751	  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
1752	  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
1753	    sh(conn, stream, IMAGE_TIMEOUT_MS)
1754	  );
1755	  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1756	    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
1757	  }
1758	  const why = tailOf(r, 2, 180);
1759	  return {
1760	    status: "failed",
1761	    detail: isEnospc(why)
1762	      ? "ran out of disk while loading the image"
1763	      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
1764	  };
1765	}
