/**
 * Canonical CPU-architecture FAMILY for the many spellings Docker/`uname` emit,
 * or "" when it is one we don't recognise. An arm64 image `docker load`s onto an
 * amd64 host without complaint and then dies at first run with "exec format
 * error", so an image transfer compares source vs target family and refuses a
 * DEFINITE mismatch. "" (unknown either side) is never a definite mismatch, so
 * an unrecognised arch is allowed through rather than blocking on a guess.
 */
function archFamily(a: string): string {
  const s = (a || "").trim().toLowerCase();
  if (/^(amd64|x86[_-]?64|x64)$/.test(s)) return "amd64";
  if (/^(arm64|aarch64)$/.test(s)) return "arm64";
  if (/^(armv[0-9]+l?|armhf|arm\/v[0-9]+|arm)$/.test(s)) return "arm";
  if (/^(i[3-6]86|ix86|x86|386)$/.test(s)) return "386";
  if (/^(ppc64le|s390x|riscv64|mips64le)$/.test(s)) return s;
  return "";
}

