/**
 * The TARGET host's CPU-architecture family, read ONCE per connection (a
 * WeakMap keyed on the live `Client`, so it is captured once yet never leaks
 * a stale arch between migrations to different hosts). `docker version` is the
 * authority; `uname -m` is the fallback if the daemon can't be queried.
 */
const _targetArchByConn = new WeakMap<Client, string>();
async function targetArch(conn: Client): Promise<string> {
  const cached = _targetArchByConn.get(conn);
  if (cached !== undefined) return cached;
  let a = clean((await sh(conn, `docker version -f '{{.Server.Arch}}' 2>/dev/null`)).stdout, 32);
  if (!a) a = clean((await sh(conn, `uname -m 2>/dev/null`)).stdout, 32);
  const fam = archFamily(a);
  _targetArchByConn.set(conn, fam);
  return fam;
}

